(* [comment removed for export] *)
Definition wb (v : Z) : Z := w_i64 (NECS.sval v).
Lemma wbound v hi :
  0 <= v < 2 ^ 64 ->
  hi <= 1 \/ (hi <= 2 /\ 127 < v < 2 ^ 64 - 32) \/ (hi <= 3 /\ 255 < v < 2 ^ 64 - 128) \/ (hi <= 5 /\ 65535 < v < 2 ^ 64 - 32768)
  \/ (hi <= 9 /\ 4294967295 < v < 2 ^ 64 - 2 ^ 31) ->
  hi <= wb v.
