Definition csl (Ri : bvmap 5 word) : Prop := forall j, In j CSL -> getr Ri (reg j) = getr R (reg j).

(* [comment removed for export] *)
Definition rq (Ri : bvmap 5 word) : Prop :=
  getr Ri (reg 2) = Z_to_bv 64 (sp - 64) /\ getr Ri (reg 8) = Z_to_bv 64 ov /\ getr Ri (reg 9) = Z_to_bv 64 v /\ getr Ri (reg 19) = Z_to_bv 64 SBL /\ csl Ri.
